// Obtener la respuesta completa del agente de IA
const fullMessage = $input.item.json.output;

// Dividir el texto en oraciones para un corte más natural
const sentences = fullMessage.match(/[^.!?]+[.!?\n\n]+/g) || [fullMessage];

// Calcular cuántas oraciones irán en cada parte
const totalSentences = sentences.length;
const sentencesPerPart = Math.ceil(totalSentences / 3);

// Crear un objeto para contener las tres partes
const messageObject = {};

// Iterar 3 veces para crear las 3 propiedades
for (let i = 0; i < 3; i++) {
  const start = i * sentencesPerPart;
  const end = start + sentencesPerPart;
  const partText = sentences.slice(start, end).join(' ').trim();

  // Asignar a una clave diferente en cada iteración (MessagePart1, MessagePart2...)
  // Si una parte está vacía, se asignará un string vacío.
  messageObject['MessagePart' + (i + 1)] = partText;
}

// Devolver un ÚNICO ítem con las tres claves
return [{ json: messageObject }];

